{"path": "/tmp/sv-524926828229472cbd2297fad7388c28/Components/Catalog/CatalogSidebar.razor", "file_text": "<aside class="catalog-sidebar">
    <h3>Filters</h3>

    <div class="filter-section">
        <h4>Category</h4>
        @foreach (var category in Categories)
        {
            <label class="filter-checkbox">
                <input type="checkbox"
                       checked="@IsSelected(category)"
                       @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                @category
            </label>
        }
    </div>

    <div class="filter-section">
        <h4>Price Range</h4>
        <div class="price-inputs">
            <label>
                Min
                <input type="number" min="0" step="0.01"
                       value="@minPrice"
                       @onchange="e => minPrice = ParseDecimal(e.Value)" />
            </label>
            <label>
                Max
                <input type="number" min="0" step="0.01"
                       value="@maxPrice"
                       @onchange="e => maxPrice = ParseDecimal(e.Value)" />
            </label>
        </div>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@inStockOnly"
                   @onchange="e => inStockOnly = (bool)e.Value!" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> selectedCategories = [];
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    private bool IsSelected(string category) => selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
        {
            if (!selectedCategories.Contains(category))
                selectedCategories.Add(category);
        }
        else
        {
            selectedCategories.Remove(category);
        }
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? new List<string>(selectedCategories) : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        selectedCategories = [];
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}
"}

{"path": "/tmp/sv-524926828229472cbd2297fad7388c28/Components/Catalog/CatalogToolbar.razor", "file_text": "<div class="catalog-toolbar">
    <div class="toolbar-sort">
        <label for="sort-select">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <div class="toolbar-info">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}
"}

{"path": "/tmp/sv-524926828229472cbd2297fad7388c28/Components/Catalog/CatalogPagination.razor", "file_text": "<nav class="catalog-pagination" aria-label="Product pagination">
    <button class="btn-page" disabled="@(Page <= 1)" @onclick="() => GoToPage(Page - 1)">
        Previous
    </button>

    @foreach (var p in GetPageNumbers())
    {
        <button class="btn-page @(p == Page ? "active" : "")"
                @onclick="() => GoToPage(p)">
            @p
        </button>
    }

    <button class="btn-page" disabled="@(Page >= TotalPages)" @onclick="() => GoToPage(Page + 1)">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; } = 1;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        // Show up to 7 page buttons centered around the current page
        const int maxButtons = 7;
        int startPage = Math.Max(1, Page - maxButtons / 2);
        int endPage = Math.Min(TotalPages, startPage + maxButtons - 1);
        startPage = Math.Max(1, endPage - maxButtons + 1);

        for (int i = startPage; i <= endPage; i++)
            yield return i;
    }
}
"}

